function parse(toks, i = 0) {
  const eat = (kind) => { if (toks[i].kind !== kind) throw new SyntaxError(`expected ${kind} at ${toks[i].pos}`); return toks[i++]; };
  function expr() {                             // one function per grammar rule
    let left = term();
    while (toks[i].kind === 'plus' || toks[i].kind === 'minus')  // loop, not left recursion
      left = { type: 'binary', op: toks[i++].kind, left, right: term() };
    return left;
  }
  return expr();
}

