const { createToken, Lexer, CstParser } = require("chevrotain");
const Plus = createToken({ name: "Plus", pattern: /\+/ });

class ExprParser extends CstParser {
  constructor() { super([Plus]); this.performSelfAnalysis(); }
  expr = this.RULE("expr", () => {
    this.SUBRULE(this.term);
    this.MANY(() => { this.CONSUME(Plus); this.SUBRULE2(this.term); });
  });
}
